import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u02")
C = "A2-B1"

L(1, "Was e had: o passado de zijn e hebben", "Ik was moe. We hadden geen tijd.",
  ["Usar o imperfectum de zijn e hebben"],
  vocab=[V("v-was","was","era|estava","verb",note="zijn → ik/jij/hij was, wij/jullie/zij waren"), V("v-waren","waren","éramos|estavam","verb"),
         V("v-had","had","tinha","verb",note="hebben → ik/jij/hij had, wij/jullie/zij hadden"), V("v-hadden","hadden","tínhamos|tinham","verb")],
  ex=[("Ik was gisteren erg moe.","Ontem estava muito cansado."),("We waren in Den Haag.","Estávamos na Haia."),("Ik had geen tijd.","Não tinha tempo."),("Ze hadden een hond.","Eles tinham um cão.")],
  gram=[G("g-imperf-zijn-hebben","Imperfectum de zijn e hebben","São irregulares. **zijn**: ik/jij/u/hij/zij **was** — wij/jullie/zij **waren**. **hebben**: ik/jij/u/hij/zij **had** — wij/jullie/zij **hadden**. No imperfectum, o singular tem uma só forma; o plural junta **-en**.",
    [("Het was koud.","Estava frio."),("Hadden jullie honger?","Vocês tinham fome?")],
    "O imperfectum corresponde muitas vezes ao nosso pretérito imperfeito («era», «tinha») em descrições.")],
  review=["v-zijn","v-hebben","v-moe","v-gisteren"],
  cefr=C, exs=[
    MA([("ik was","eu era/estava"),("wij waren","nós éramos"),("ik had","eu tinha"),("zij hadden","eles tinham")], "Formas do passado.", ["v-was","v-waren","v-had","v-hadden"]),
    CJ("zijn","wij","Wij ___ gisteren in Utrecht.", ["waren"], "Plural → waren.", ["v-waren"], tense="passado-simples"),
    CJ("hebben","ik","Ik ___ geen geld bij me.", ["had"], "Singular → had.", ["v-had"], tense="passado-simples"),
    CJ("hebben","jullie","___ jullie een leuke tijd?", ["Hadden"], "Plural → hadden.", ["v-hadden"], tense="passado-simples"),
    TR("pt-nl","Ontem estava muito cansado.", ["Ik was gisteren [erg|heel] moe","Gisteren was ik [erg|heel] moe"], "ik was.", ["v-was"]),
    TR("nl-pt","We hadden geen tijd.", ["Não tínhamos tempo","Nós não tínhamos tempo"], "hadden.", ["v-hadden"]),
    FE(["Wij","was","heel","blij."], 1, "waren", "Wij → waren.", ["v-waren"]),
    FB("Het ___ een mooie dag.", ["was"], "Het → was.", ["v-was"], choices=["was","waren","had"], tr="Foi/Estava um dia bonito."),
    LI("Waren jullie gisteren thuis?", ["Waren jullie gisteren thuis"], "Vocês estavam em casa ontem?", "waren.", ["v-waren"]),
    WO("Eles tinham um cão.", ["Ze","hadden","een","hond"], "hadden.", ["v-hadden"]),
  ], diff=3, mins=6)

L(2, "Verbos regulares: -te e -de", "Ik werkte, ik woonde: a regra 't kofschip.",
  ["Formar o imperfectum dos verbos regulares"],
  vocab=[V("v-werkte","werkte","trabalhava|trabalhou","verb",note="werken → werkte(n)"), V("v-woonde","woonde","morava|morou","verb",note="wonen → woonde(n)"),
         V("v-speelde","speelde","jogava|brincava","verb",note="spelen → speelde(n)"), V("v-maakte","maakte","fazia|fez","verb",note="maken → maakte(n)")],
  ex=[("Ik werkte in een restaurant.","Trabalhava num restaurante."),("We woonden in Lissabon.","Morávamos em Lisboa."),("Als kind speelde ik veel buiten.","Em criança brincava muito lá fora."),("Hij maakte een fout.","Ele fez um erro.")],
  gram=[G("g-imperf-regular","Imperfectum regular: 't kofschip","Junta-se ao radical **-te(n)** se ele terminar numa consoante de **'t kofschip** (t, k, f, s, ch, p): *werk → werkte*, *maak → maakte*. Nos outros casos, **-de(n)**: *woon → woonde*, *speel → speelde*. Plural: **-ten/-den**.",
    [("Ik fietste naar school.","Ia de bicicleta para a escola."),("Zij woonden in Gent.","Eles moravam em Gante.")],
    "É a mesma regra que decide -t/-d no particípio (gewerkt, gewoond).")],
  review=["v-werken","v-wonen","v-spelen","v-maken"],
  cefr=C, exs=[
    MA([("werken","werkte"),("wonen","woonde"),("spelen","speelde"),("maken","maakte")], "Infinitivo e passado.", ["v-werkte","v-woonde","v-speelde","v-maakte"]),
    CJ("werken","ik","Ik ___ vroeger in een hotel.", ["werkte"], "werk + -te (k está em 't kofschip).", ["v-werkte"], tense="passado-simples"),
    CJ("wonen","wij","Wij ___ toen in Porto.", ["woonden"], "woon + -den.", ["v-woonde"], tense="passado-simples"),
    CJ("fietsen","hij","Hij ___ elke dag naar zijn werk.", ["fietste"], "fiets + -te (s).", [], tense="passado-simples"),
    MC("Qual é o imperfectum de «spelen» (ik)?", ["*speelde","speelte|«l» não está em 't kofschip → -de.","speelden|Isso é o plural."], "speel + de.", ["v-speelde"]),
    FE(["Ik","maakde","het","eten","klaar."], 1, "maakte", "k está em 't kofschip → maakte.", ["v-maakte"]),
    TR("pt-nl","Morávamos em Lisboa.", ["We woonden in Lissabon","Wij woonden in Lissabon"], "woonden.", ["v-woonde"]),
    TR("nl-pt","Als kind speelde ik veel buiten.", ["Em criança brincava muito lá fora","Quando era criança brincava muito lá fora","Em criança eu brincava muito na rua"], "speelde.", ["v-speelde"]),
    LI("Wat maakte je daar?", ["Wat maakte je daar","Wat maakte jij daar"], "O que fazias lá?", "maakte.", ["v-maakte"]),
    FB("Mijn ouders ___ allebei in een fabriek.", ["werkten"], "Plural: -ten.", ["v-werkte"], choices=["werkten","werkte","werkden"], tr="Os meus pais trabalhavam ambos numa fábrica."),
  ], diff=3, mins=7)

L(3, "Verbos irregulares no imperfectum", "ging, kwam, zag, at, dronk, liep…",
  ["Usar o imperfectum de verbos irregulares frequentes"],
  vocab=[V("v-ging","ging","ia|foi","verb",note="gaan → ging / gingen"), V("v-kwam","kwam","vinha|veio","verb",note="komen → kwam / kwamen"),
         V("v-zag","zag","via|viu","verb",note="zien → zag / zagen"), V("v-at","at","comia|comeu","verb",note="eten → at / aten"),
         V("v-liep","liep","andava|caminhou","verb",note="lopen → liep / liepen")],
  ex=[("Ik ging naar de markt.","Fui ao mercado."),("Hij kwam te laat.","Ele chegou atrasado."),("We zagen een mooie film.","Vimos um filme bonito."),("Ze at een appel.","Ela comeu uma maçã.")],
  gram=[G("g-imperf-irreg","Imperfectum irregular","Os verbos fortes mudam a vogal e **não** levam -te/-de: *gaan → ging*, *komen → kwam*, *zien → zag*, *eten → at*, *drinken → dronk*, *lopen → liep*. No plural junta-se **-en**: *gingen, kwamen, zagen, aten*.",
    [("Wij dronken koffie.","Bebíamos/Bebemos café."),("Zij liepen naar huis.","Eles foram a pé para casa.")])],
  review=["v-gaan","v-komen","v-zien","v-eten","v-lopen"],
  cefr=C, exs=[
    MA([("gaan","ging"),("komen","kwam"),("zien","zag"),("eten","at"),("lopen","liep")], "Formas irregulares.", ["v-ging","v-kwam","v-zag","v-at","v-liep"]),
    CJ("gaan","ik","Gisteren ___ ik naar de markt.", ["ging"], "gaan → ging.", ["v-ging"], tense="passado-simples"),
    CJ("komen","wij","Wij ___ om acht uur thuis.", ["kwamen"], "komen → kwamen.", ["v-kwam"], tense="passado-simples"),
    CJ("zien","zij (ela)","Ze ___ haar vriendin in de stad.", ["zag"], "zien → zag.", ["v-zag"], tense="passado-simples"),
    FE(["Hij","gaatte","naar","huis."], 1, "ging", "gaan é irregular: ging.", ["v-ging"]),
    TR("pt-nl","Vimos um filme bonito.", ["We zagen een mooie film","Wij zagen een mooie film"], "zagen.", ["v-zag"]),
    TR("nl-pt","Hij kwam te laat.", ["Ele chegou atrasado","Ele veio tarde","Ele chegou tarde"], "kwam.", ["v-kwam"]),
    MC("Qual é o imperfectum de «drinken» (wij)?", ["*dronken","drinkten|Drinken é irregular.","gedronken|Isso é o particípio."], "drinken → dronk/dronken.", []),
    BS("Fomos a pé para casa.", ["We","liepen","naar","huis","lopen"], ["We liepen naar huis"], "liepen; «lopen» sobra.", ["v-liep"]),
    LI("Wat at je als ontbijt?", ["Wat at je als ontbijt","Wat at jij als ontbijt"], "O que comias/comeste ao pequeno-almoço?", "at.", ["v-at"]),
  ], diff=4, mins=7)

L(4, "Contar uma história: eerst, toen, daarna", "Sequência narrativa e inversão depois de toen.",
  ["Encadear acontecimentos com eerst, toen, daarna, uiteindelijk"],
  vocab=[V("v-toen","toen","então|nessa altura","adverb",note="Toen ging ik naar huis. (inversão)"), V("v-plotseling","plotseling","de repente","adverb"),
         V("v-uiteindelijk","uiteindelijk","por fim|afinal","adverb"), V("v-verhaal","verhaal","história","noun","het","verhalen")],
  ex=[("Eerst ging ik naar de bakker, toen naar de slager.","Primeiro fui ao padeiro, depois ao talho."),("Plotseling begon het te regenen.","De repente começou a chover."),("Uiteindelijk kwamen we thuis.","Por fim chegámos a casa."),("Vertel eens een verhaal!","Conta lá uma história!")],
  gram=[G("g-narrativa","Advérbio no início → inversão","Quando a frase começa por **eerst, toen, daarna, plotseling, uiteindelijk**, o verbo vem logo a seguir e só depois o sujeito: *Toen **ging ik** naar huis.* O verbo conjugado fica sempre na 2.ª posição.",
    [("Daarna gingen we eten.","Depois fomos comer."),("Plotseling zag ik mijn buurman.","De repente vi o meu vizinho.")],
    "Em português dizemos «depois eu fui»; em neerlandês é obrigatório «depois fui eu».")],
  review=["v-eerst","v-daarna","v-ging","v-kwam"],
  cefr=C, exs=[
    MA([("toen","então"),("plotseling","de repente"),("uiteindelijk","por fim"),("verhaal","história")], "Narrar.", ["v-toen","v-plotseling","v-uiteindelijk","v-verhaal"]),
    WO("Depois fomos comer.", ["Daarna","gingen","we","eten"], "Inversão: Daarna gingen we.", ["v-daarna"]),
    WO("De repente vi o meu vizinho.", ["Plotseling","zag","ik","mijn","buurman"], "Inversão depois de plotseling.", ["v-plotseling"]),
    FE(["Toen","ik","ging","naar","huis."], 1, "ging", "Depois de «toen» vem o verbo: Toen ging ik naar huis.", ["v-toen"]),
    TR("pt-nl","Por fim chegámos a casa.", ["Uiteindelijk kwamen we thuis","Uiteindelijk kwamen wij thuis"], "Inversão.", ["v-uiteindelijk"]),
    TR("nl-pt","Plotseling begon het te regenen.", ["De repente começou a chover"], "plotseling.", ["v-plotseling"]),
    AR("verhaal","a história","het", "Het verhaal.", ["v-verhaal"]),
    CO("text","Een rare dag", "Gisteren ging ik met de fiets naar mijn werk. Eerst was het mooi weer, maar toen begon het plotseling hard te regenen. Ik had geen jas bij me. Uiteindelijk kwam ik helemaal nat op kantoor aan. Mijn collega's lachten, maar ze gaven me een kop thee.",
       [("Porque chegou molhado?", ["*Começou a chover e não tinha casaco","Caiu num canal","Lavou a bicicleta"]),("O que fizeram os colegas?", ["*Riram-se e deram-lhe chá","Mandaram-no para casa","Não disseram nada"])],
       "Repare na sequência eerst → toen → uiteindelijk.", ["v-toen","v-plotseling","v-uiteindelijk"]),
    LI("Toen gingen we naar huis.", ["Toen gingen we naar huis","Toen gingen wij naar huis"], "Então fomos para casa.", "Inversão.", ["v-toen"]),
    FB("___ begon het te sneeuwen.", ["Plotseling"], "Advérbio no início, verbo a seguir.", ["v-plotseling"], choices=["Plotseling","Ik","Het"], tr="De repente começou a nevar."),
  ], diff=4, mins=7)

L(5, "Perfectum ou imperfectum?", "Quando se usa cada um ao contar algo.",
  ["Escolher entre perfectum e imperfectum num relato"],
  vocab=[V("v-vroeger","vroeger","antigamente|dantes","adverb"), V("v-elke-zomer","elke zomer","todos os verões","expression"),
         V("v-gebeuren","gebeuren","acontecer","verb",note="Wat is er gebeurd? (zijn)"), V("v-gebeurd","gebeurd","acontecido","verb")],
  ex=[("Wat is er gebeurd?","O que aconteceu?"),("Vroeger woonde ik in Faro.","Antigamente morava em Faro."),("Elke zomer gingen we naar het strand.","Todos os verões íamos à praia."),("Ik heb mijn telefoon verloren.","Perdi o telemóvel.")],
  gram=[G("g-perf-vs-imperf","Perfectum vs. imperfectum","Na conversa, para **um facto** passado (resultado, novidade), usa-se sobretudo o **perfectum**: *Ik heb mijn telefoon verloren.* Para **descrever**, **hábitos** (*vroeger, elke zomer*) e para **contar uma história** em sequência, usa-se muito o **imperfectum**: *Vroeger woonde ik in Faro.* Muitas histórias começam no perfectum e continuam no imperfectum.",
    [("Ik ben naar Gent geweest. Het was erg gezellig.","Estive em Gante. Foi muito agradável."),("Vroeger speelden we elke dag buiten.","Antigamente brincávamos lá fora todos os dias.")],
    "O imperfectum aproxima-se do nosso imperfeito (hábitos, descrições).")],
  review=["v-was","v-ging","v-werkte","v-ervaring"],
  cefr=C, exs=[
    MA([("vroeger","antigamente"),("elke zomer","todos os verões"),("gebeuren","acontecer"),("gebeurd","acontecido")], "Tempo e hábito.", ["v-vroeger","v-elke-zomer","v-gebeuren","v-gebeurd"]),
    MC("Hábito antigo: «Antigamente morava em Faro.»", ["*Vroeger woonde ik in Faro.","Vroeger heb ik in Faro gewoond.|Possível, mas o imperfectum é o mais natural para um hábito/situação antiga.","Vroeger woon ik in Faro.|Presente."], "Situação antiga → imperfectum.", ["v-vroeger"]),
    MC("Notícia a um amigo: «Perdi o telemóvel!»", ["*Ik heb mijn telefoon verloren!","Ik verloor mijn telefoon!|Soa a relato literário; na conversa usa-se o perfectum.","Ik verlies mijn telefoon!|Presente."], "Facto/resultado → perfectum.", []),
    TR("pt-nl","O que aconteceu?", ["Wat is er gebeurd"], "gebeuren → zijn gebeurd.", ["v-gebeurd"]),
    TR("pt-nl","Todos os verões íamos à praia.", ["Elke zomer gingen we naar het strand","Elke zomer gingen wij naar het strand","We gingen elke zomer naar het strand"], "Hábito → imperfectum; inversão.", ["v-elke-zomer"]),
    FE(["Wat","heeft","er","gebeurd?"], 1, "is", "gebeuren usa zijn: Wat is er gebeurd?", ["v-gebeurd"]),
    WO("Antigamente brincávamos lá fora.", ["Vroeger","speelden","we","buiten"], "Inversão depois de vroeger.", ["v-vroeger"]),
    DL([("Lotte","Je ziet er moe uit. Wat is er gebeurd?","Pareces cansado. O que aconteceu?"),("João","")], ["*Ik heb slecht geslapen. De buren hadden een feest.","Ik slaap slecht.|Não responde ao que aconteceu.","Er gebeurt niets morgen.|Não faz sentido."], "Perfectum para o facto + imperfectum para a descrição.", ["v-gebeurd","v-hadden"]),
    LI("Vroeger was alles anders.", ["Vroeger was alles anders"], "Antigamente era tudo diferente.", "was.", ["v-vroeger"]),
    SW("Escreva 3 frases sobre a sua infância: onde morava, o que fazia todos os verões e um acontecimento especial.", ["Vroeger woonde ik in Aveiro. Elke zomer gingen we naar het strand. Op mijn tiende ben ik naar Parijs geweest."], ["Usou **imperfectum** para hábitos (woonde, gingen)", "Inversão depois de **vroeger/elke zomer**", "Usou o **perfectum** para um acontecimento"], 15, "Combinar os dois tempos.", ["v-vroeger","v-elke-zomer"]),
  ], diff=4, mins=8)

W()
